import{_ as t,o as r,c as a,ag as n}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"Retainer burn check","description":"","frontmatter":{},"headers":[],"relativePath":"playbook/retainer-burn-check.md","filePath":"playbook/retainer-burn-check.md"}'),o={name:"playbook/retainer-burn-check.md"};function i(s,e,l,h,c,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="retainer-burn-check" tabindex="-1">Retainer burn check <a class="header-anchor" href="#retainer-burn-check" aria-label="Permalink to &quot;Retainer burn check&quot;">​</a></h1><p><strong>Cadence</strong>: Weekly · <strong>Who</strong>: Managers and Owners</p><h2 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h2><p>You want to know whether any retainer is running hot — burning hours faster than its monthly period can absorb — before you&#39;re past the point of renegotiating.</p><p>The worst retainer problem is one you discover at month-end. This play catches it at week one.</p><h2 id="in-the-console" tabindex="-1">In the console <a class="header-anchor" href="#in-the-console" aria-label="Permalink to &quot;In the console&quot;">​</a></h2><p>In the <strong>Projects</strong> list (<code>/console</code>), retainers report their <strong>active period</strong> burn — hours used, % used, status — so you&#39;re reading the month that&#39;s live, not the parent. Scan for anything in warning or critical, then open one to see the period detail.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>A table of every active retainer period:</p><p>| Client | Project | Hours budget | Hours used | % used | Days left | Status |</p><p>Sorted: critical first, then warning, then on-track.</p><p>Thresholds:</p><ul><li><strong>Critical</strong> — already over 100% for this period</li><li><strong>Warning</strong> — pacing to finish over budget at current burn</li><li><strong>On-track</strong> — pacing at or under budget</li></ul><p>For Owners, the table also shows contract value and projected margin for the period.</p><h2 id="who-can-run-it" tabindex="-1">Who can run it <a class="header-anchor" href="#who-can-run-it" aria-label="Permalink to &quot;Who can run it&quot;">​</a></h2><ul><li><strong>Owners</strong> — full view including dollar amounts</li><li><strong>Managers</strong> — percentages and hours only, on their assigned retainers</li></ul><h2 id="related-plays" tabindex="-1">Related plays <a class="header-anchor" href="#related-plays" aria-label="Permalink to &quot;Related plays&quot;">​</a></h2><ul><li><a href="./monday-portfolio-read.html">Monday portfolio read</a> — the broader weekly view</li><li><a href="./project-health-probe.html">Project health probe</a> — deep dive on a single retainer</li><li><a href="./month-end-margin-review.html">Month-end margin review</a> — what this rolls up into</li></ul>',18)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
